p2 = D + r"\DESERVE.tsv"
rows = io.open(p2, encoding="utf-8", newline="").read().split("\n")
m = 0
for k, line in enumerate(rows):
    f = line.split("\t")
    if len(f) >= 7 and f[1] == "TOP200_RETIRED" and "to be checked against the literature" in f[5]:
        f[5] = "canonical; retirement source checked in LITCHECK.tsv"; rows[k] = "\t".join(f); m += 1
